# problem P-09b1eb (generated by opus): For a finite set $A\subseteq\mathbb N_0$ and $n\in\mathbb N_0$ let $\sigma_A(n)=|\{(a,a')\in A^2: a+a'=n\}|$ be the number of ordered representations. For $k\in\mathbb N$ let $N_k\in\mathbb N_0\cup\{\infty\}$ be the supremum of all $N$ for which some $A\subseteq\{0,1,\dots,N\}$ satisfies $\{0,1,\dot
# finite_form: Take $N=2000$ and $k=8$. Find a set $A\subseteq\{0,1,\dots,2000\}$ such that every $n\in\{0,\dots,2000\}$ has $\sigma_A(n)\ge1$ and $\sigma_A(n)\le 8$, where $\sigma_A(n)$ is the number of ordered pairs $(a,a')\in A^2$ with $a+a'=n$.
# candidate_format: A JSON array of distinct integers, each between 0 and 2000 inclusive (the elements of A).

def check(candidate) -> bool:
    try:
        N = 2000
        K = 8
        if not isinstance(candidate, list):
            return False
        if len(candidate) > N + 1:
            return False
        for x in candidate:
            if isinstance(x, bool) or not isinstance(x, int):
                return False
            if x < 0 or x > N:
                return False
        if len(set(candidate)) != len(candidate):
            return False
        A = sorted(candidate)
        cnt = [0] * (N + 1)
        L = len(A)
        for i in range(L):
            a = A[i]
            for j in range(i, L):
                s = a + A[j]
                if s > N:
                    break
                if i == j:
                    cnt[s] += 1
                else:
                    cnt[s] += 2
                if cnt[s] > K:
                    return False
        for n in range(N + 1):
            if cnt[n] < 1 or cnt[n] > K:
                return False
        return True
    except Exception:
        return False
